pub(crate) struct InstalledLocalModel {
    pub(crate) name: String,
    pub(crate) digest: Option<String>,
    pub(crate) size_bytes: Option<u64>,
    pub(crate) parameter_size: Option<String>,
    pub(crate) quantization_level: Option<String>,
    pub(crate) family: Option<String>,
    pub(crate) capabilities: Vec<String>,
}

impl InstalledLocalModel {
    pub(crate) fn supports_capability(&self, capability: &str) -> bool {
        self.capabilities
            .iter()
            .any(|value| value.eq_ignore_ascii_case(capability))
    }
}
